insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('coilovers','bpy','Coilover install','Suspension',null,array['coilovers','coilover','lowering','kw','bilstein','st suspension','bc racing','ride height','struts','shocks']::text[],true,'6–8 hr',3.5) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('coilovers',$j${"id": "coilovers", "title": "Coilover install", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "coilover-hero", "alsoFits": "Mk5/Mk6 Golf, GTI, Jetta, Eos · A3 8P (same PQ35 strut and multilink rear)", "category": "Suspension", "kind": "upgrade", "variants": {"question": "Does your kit include its own top mounts?", "hint": "Most European kits (KW, Bilstein, H&R, ST, Koni) reuse the factory strut mounts and bearings, so the old struts have to come apart. Kits with their own mounts or camber plates (BC Racing, some ECS kits) bolt straight in.", "options": [{"id": "reuse", "label": "Reuses factory mounts", "when": "KW, Bilstein, H&R, ST, Koni. Spring compressor needed, or buy new mounts."}, {"id": "own", "label": "Includes top mounts / camber plates", "when": "BC Racing, ECS kits with HD mounts. Stock struts stay assembled."}]}, "glance": {"timeFirst": "6–8 hr (a full day)", "timeRepeat": "4 hr", "difficulty": 3.5, "cost": "$900–2,500 + alignment", "risk": "Compressed springs · seized pinch bolts · axle bolt at 200 Nm · alignment required", "why": "Coilovers replace the springs and dampers at all four corners with adjustable ones: you set the ride height, and on adjustable kits the damping. It's the biggest single change you can make to how the car drives, and the most involved bolt-on in this app after the clutch.", "note": "ECS rates it moderate; owners say a full day, two if a pinch bolt is seized. The alignment afterwards is not optional."}, "heroCap": "Front: strut clamped in the wheel-bearing housing by one pinch bolt, hung from three bolts under the cowl. Rear: separate spring in the control arm and a shock on two upper bolts and one big lower bolt.", "lifespan": {"title": "When owners do this", "headline": ["Usually after sway bars and tires, or when the original dampers are done around 100,000 miles"], "earliest": null, "detail": "Original dampers on a 2006 car are tired by now; a bouncy ride, nose-dive under braking and inner-edge tire wear are the signs. Owners choosing between new factory-style dampers and coilovers usually go coilover because the price gap has closed and the springs come with it.", "factors": ["Worn original dampers", "Sway bars already fitted", "Want the stance"], "inspect": ["Bounce test each corner: more than one rebound means the damper is gone"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus; no factory interval for dampers."}}, "should": {"yesIf": ["Original dampers are worn", "You want adjustable ride height and, on some kits, damping", "Sway bars are done and you want the next step", "You have a full day, a helper for the front struts, and an alignment booked"], "codes": [], "notes": ["Buy the installation kit, or its parts: new strut mounts and bearings, pinch bolts and nuts, axle bolts, rear shock mounts and bolts. Half of these are torque-to-yield and all of them are twenty years old. The kit also saves you a spring compressor if your coilovers reuse factory mounts.", "Lower it sensibly. Below about 1.5 inches of drop on a PQ35 car the geometry goes off, inner tires wear fast, and you'll want camber correction and adjustable end links. Set height for how you drive, not for the photo.", {"text": "Reusing the factory mounts means compressing the old springs to get the mounts off. A spring compressor is the most dangerous tool in a home garage. Rent a good one, use both claws, and never put any part of you in line with the spring.", "only": ["reuse"]}], "confidence": {"level": "high", "n": 4, "note": "Procedure agrees across the manufacturer guide and owner DIYs; the parts-replacement advice is universal."}}, "parts": [{"tier": "aftermarket", "name": "Coilover kit (4 corners)", "pn": "see options below", "note": "", "price": "$900–2,500", "links": []}, {"tier": "oe", "name": "Front strut mounts (×2) and bearings (×2)", "pn": "1K0 412 331 B · 6N0 412 249 C", "note": "Old ones are worn and you're compressing springs to reuse them", "price": "$60–120", "links": [], "only": ["reuse"]}, {"tier": "oe", "name": "Front pinch bolts and nuts (×2)", "pn": "M14, torque-to-yield", "note": "Replace", "price": "$15", "links": []}, {"tier": "oe", "name": "Outer axle bolts (×2)", "pn": "24mm 12-point, torque-to-yield", "note": "Replace", "price": "$20", "links": []}, {"tier": "oe", "name": "Rear shock mounts (×2) and upper bolts", "pn": "1K0 513 353 G", "note": "Cheap; replace", "price": "$40", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Book it for the day after", "price": "$100–150", "links": []}], "aftermarket": [{"name": "KW V1 / V2 / V3", "note": "Stainless bodies, reuse factory mounts. V1 fixed damping, V2 rebound-adjustable, V3 rebound and compression. The reference kit; priced like it.", "price": "$1,400–2,500", "signal": "Reference kit", "links": []}, {"name": "Bilstein B14 (PSS) / B16 (PSS10)", "note": "B14 fixed damping, B16 ten-click adjustable. Reuse factory mounts. Firm, controlled, long-lived.", "price": "$1,200–2,200", "signal": "Daily-and-track pick", "links": []}, {"name": "ST X / XA / XTA", "note": "KW's value brand, same threads and install. XA adds damping, XTA adds camber plates (so it needs no factory mounts).", "price": "$900–1,700", "signal": "Value pick", "links": []}, {"name": "H&R Street Performance", "note": "Reuse factory mounts; comfortable side of the range; H&R's spring rates.", "price": "$1,100–1,500", "signal": "Comfort pick", "links": []}, {"name": "BC Racing BR", "note": "Includes camber plates and top mounts, 30-way damping, rear separate spring perch. No spring compressor needed. Softer bodies; the price shows.", "price": "$1,000–1,300", "signal": "Own mounts included", "links": []}, {"name": "ECS Tuning adjustable kit", "note": "Budget kit; the ECS install PDF this guide follows was written around a similar design. Pair with their install kit.", "price": "$700–900", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_6302_Volkswagen_MK5-6_Coilover_Installation_Instructions.pdf"}]}], "tools": [{"name": "Jack, four stands, a second jack for the control arms; wheel hanger helps"}, {"name": "M14 triple-square (pinch bolt) and M6 triple-square (end links); 24mm 12-point socket and a breaker bar or impact (axle bolt)"}, {"name": "Spindle housing spreader tool", "note": "The strut will not come out of the housing without it; rent or buy (ECS ES#3894)"}, {"name": "Strut nut sockets (21/22mm pass-through) and a 7mm hex to hold the rod; 19mm offset wrench for the rear"}, {"name": "Spring compressor (rent a good one)", "only": ["reuse"]}, {"name": "Sockets 10, 13, 16, 18, 21mm; torque wrench to 200 Nm; angle gauge or paint pen; penetrating oil; tape measure"}], "before": ["Measure fender-to-ground at all four corners on level ground and write it down. It's your only reference for setting height.", "Soak the pinch bolts, axle bolts and end-link nuts the night before.", "Loosen the axle bolts with the wheels on the ground or a helper on the brakes, never with the wheel off the ground and the bearing taking the load.", "Do fronts first (harder), then rears. Both sides of an axle before you move on."], "steps": [{"n": 1, "title": "Measure, raise, wheels off", "blocks": [{"t": "text", "b": "Fender heights recorded. Loosen the two axle bolts (24mm 12-point) with the car on the ground. Raise it on four stands, all wheels off."}]}, {"n": 2, "title": "Front: disconnect around the strut", "blocks": [{"t": "text", "b": "End-link nut at the strut (18mm, M6 triple-square holding the stud). Brake hose and ABS wire bracket bolt (10mm) off the bearing housing; don't stretch the hose. Axle bolt fully out. Driver's side: level-sensor arm bracket off the control arm (10mm). Three ball-joint nuts (16mm), pry the control arm down off the joint, pull the bearing housing outward so the CV joint comes out of the hub, and wire the shaft up. Reconnect the ball joint loosely so the arm is controlled."}, {"t": "ill", "id": "coilover-hero", "cap": "Front strut: one pinch bolt below, three bolts above. The housing has to be spread to release it."}]}, {"n": 3, "title": "Front: pinch bolt and spreader", "caution": true, "blocks": [{"t": "text", "b": "Jack under the control arm. Pinch bolt out: M14 triple-square one side, 18mm the other. Spreader tool into the slot at the back of the bearing housing, rotate it to open the gap, then lower the jack and tap the housing down off the strut with a hammer until it's free."}, {"t": "warn", "b": "A seized pinch bolt is where the day goes. Heat, oil and patience; if the triple-square rounds, you're drilling. Never hammer the housing without the spreader in; the aluminium cracks."}]}, {"n": 4, "title": "Front: strut out from the top", "blocks": [{"t": "text", "b": "Peel back the cowl seal at the strut tower to reach the three 13mm top bolts. One hand on the strut, remove all three, and lower it out of the car."}]}, {"n": 5, "title": "Front: strip the old mounts", "only": ["reuse"], "caution": true, "blocks": [{"t": "text", "b": "Old strut in a vise. Spring compressor on, both claws, compressed until the spring lifts off the upper seat. Hold the rod with a 7mm hex, remove the top nut with a 21mm strut socket, lift the mount and bearing off. Release the compressor slowly. Inspect: if the bearing is notchy or the mount's rubber is cracked, use new ones instead."}, {"t": "warn", "b": "A compressed coil spring stores enough energy to kill. Claws seated, hooks facing each other, never over the ends of the spring. Do this on the bench, never in the car."}]}, {"n": 6, "title": "Front: build the coilover", "blocks": [{"t": "text", "b": "Light grease on the threads. Perch and lock ring threaded to the bottom. Spring on, kit's upper spacer, then the mount and bearing (new, or the factory ones you just freed). Arrows or marks on the mount point fore and aft. New top nut, rod held with a 7mm hex.", "only": ["reuse"]}, {"t": "text", "b": "Light grease on the threads. Perch and lock ring to the bottom, spring on, then the kit's top mount or camber plate per its sheet: camber plates have a marked orientation and an adjustment slot that should start centred. New top nut, rod held with a hex.", "only": ["own"]}, {"t": "torque", "label": "Front strut top nut", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm from the manufacturer guide and the Koni owner DIY. Kit-supplied nuts may differ; check."}}, {"t": "text", "b": "Wind the perch up until the spring just touches both seats. Height comes later."}]}, {"n": 7, "title": "Front: into the car", "blocks": [{"t": "text", "b": "Up into the tower, mount arrows fore/aft, three new top bolts started. Spreader back in the housing, jack the control arm up and guide the strut's foot fully into the housing until it bottoms on the stop, then a new pinch bolt and nut."}, {"t": "torque", "label": "Upper strut mount bolts (×3)", "nm": 15, "c": {"level": "high", "n": 2, "note": "15 Nm + 90°, new bolts (manufacturer; forum tables agree)."}, "note": "+90° turn"}, {"t": "torque", "label": "Pinch bolt (M14)", "nm": 70, "c": {"level": "high", "n": 2, "note": "70 Nm + 90°, new bolt and nut (manufacturer, forum). The Mk7 figure of 70 + 180° is a different car."}, "note": "+90° turn"}, {"t": "text", "b": "Ball joint back on (60 Nm cast arm, 100 Nm aluminium), CV into the hub, new axle bolt started, level sensor, brake bracket, end link (65 Nm). Other side. Wheels on at 120 Nm; final axle-bolt torque with the car on the ground."}, {"t": "torque", "label": "Outer axle bolt (NEW)", "nm": 200, "alt": [70], "c": {"level": "varies", "n": 2, "note": "Depends on the bolt: hex head or smooth 12-point is 200 Nm + 180°; a ribbed 12-point is 70 Nm + 90°. The owner DIY's '180 or 200' confusion is this. Look at the underside of the bolt head."}, "note": "+180° / +90°"}]}, {"n": 8, "title": "Rear: shock and spring out", "blocks": [{"t": "text", "b": "Driver's side: level-sensor arm nut (10mm). Lower shock bolt (21mm). Two upper shock bolts (13mm on a long extension) and the shock comes down. Jack under the control arm; counter-hold and remove the outer control-arm bolt (18mm both sides), then lower the jack and lift the spring out of its cushion."}]}, {"n": 9, "title": "Rear: build and fit", "blocks": [{"t": "text", "b": "New rear shock: mount (new, or the old one freed with a 16mm and a hex on the rod) onto the rod, upper nut to 25 Nm with a 19mm offset wrench. Rear spring: kit's perch into the top of the spring with the collar wound up (or, on kits with a lower perch, pry the factory lower cushion out of the arm and fit the kit's perch and collar there). Spring into the arm, end coil against its stop, aligned with the body's centring pin."}, {"t": "torque", "label": "Rear shock upper mount bolts (×2)", "nm": 50, "c": {"level": "high", "n": 2, "note": "50 Nm + 45° (manufacturer)."}, "note": "+45° turn"}, {"t": "text", "b": "Shock up and its two upper bolts torqued. Jack the arm until the outer arm bolt slides in; nut on loose. Lower shock bolt in, not torqued."}]}, {"n": 10, "title": "Rear torques at ride height", "caution": true, "blocks": [{"t": "text", "b": "The lower shock bolt and the outer control-arm bolt clamp rubber bushings; torqued in the air they'd be wound up at the wrong angle. Wheels on (120 Nm), lower the car onto its wheels (or onto ramps), then torque both."}, {"t": "torque", "label": "Rear shock lower bolt", "nm": 180, "c": {"level": "high", "n": 2, "note": "180 Nm at ride height (manufacturer). Not the Mk7's 70 + 180°."}}, {"t": "torque", "label": "Rear outer control-arm bolt", "nm": 90, "c": {"level": "high", "n": 2, "note": "90 Nm + 90° at ride height, new bolt."}, "note": "+90° turn"}, {"t": "warn", "b": "On stands, these bolts are just snug. Torque only with the weight on the wheels. Forgetting this is how bushings tear in a month."}]}, {"n": 11, "title": "Set ride height", "blocks": [{"t": "text", "b": "Lift the car so the springs are unloaded (weight off), wind the perches to your target using the measurements from step 1 (a sensible street drop is 1 to 1.5 inches), lower, roll it a few feet, re-measure, repeat. Left and right within a few millimetres. Tighten the front lock rings against the perches. Turn the wheel lock to lock and bounce each corner: nothing touches."}]}, {"n": 12, "title": "Alignment, then re-check", "blocks": [{"t": "text", "b": "Alignment next day, after the springs have settled. Re-measure height after a week; kits settle a few millimetres. Re-check the pinch bolts and end links at 100 miles. Set damping (if adjustable) from the maker's baseline and change one click at a time."}]}], "alsoReplace": [{"name": "Strut mounts and bearings", "why": "They're off the strut (or in the way of it). Notchy steering return and clunks over bumps come from these.", "only": ["reuse"]}, {"name": "Adjustable sway-bar end links", "why": "Lowering shortens the link geometry; adjustable links let the bars sit unloaded at the new height."}, {"name": "Rear shock mounts", "why": "Cheap rubber on a 20-year-old car; they're in your hand."}, {"name": "Camber correction (front camber bolts or plates; rear camber/toe kit)", "why": "Below about 1.5 inches of drop the factory adjustment range runs out and the alignment shop will tell you so."}, {"name": "Front control-arm bushings and dogbone mount", "why": "You've pulled the ball joints; a look at the arm bushings costs nothing, and a worn dogbone shows up more with stiffer suspension."}], "check": {"tab": "How low?", "title": "How low, and how stiff?", "illId": "coilover-hero", "illCap": "Height and damping are separate decisions.", "rows": [{"see": "Daily driver, rough roads", "means": "You want control, not slam.", "do": "1 inch drop, damping at or near the maker's baseline. Bilstein B14, H&R, ST X."}, {"see": "Spirited street, occasional track", "means": "Adjustable damping earns its keep.", "do": "1–1.5 inch, adjustable kit (KW V2/V3, B16, ST XA), adjustable end links, alignment with a little extra negative camber."}, {"see": "Show car", "means": "Looks first.", "do": "Go low, but budget for camber correction, adjustable links and tire wear, and expect the ride to suffer."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; the geometry point is standard suspension practice."}}, "aftercare": ["Alignment after settling.", "Re-torque pinch bolts and end links at 100 miles; re-measure height at a week.", "Grease the threads and lock rings once a year in the salt belt or they seize."], "disagreements": [{"topic": "How hard?", "pos": "Manufacturer: 'Moderate, a couple of hours'. Owners: a full day, more if the pinch bolt fights.", "call": "3.5 out of 5 and a full day."}, {"topic": "Axle bolt torque", "pos": "'180 or 200 Nm depending on which page of Bentley' (owner). Manufacturer table gives three values by bolt type.", "call": "By bolt type. Check the head."}, {"topic": "Brand-specific steps?", "pos": "Brands differ in details.", "call": "The manufacturer guide is explicitly cross-brand and the procedure matches the owner DIYs. The real fork is whether your kit brings its own top mounts, which is the question the guide asks."}], "sources": ["ECS Tuning Mk5/Mk6 coilover installation PDF (2018, cross-brand)", "VWVortex Koni coilover install DIY (part numbers, tools)", "Golfmk7 spring/damper reference (excluded values noted)", "Brand listings: KW, Bilstein, ST, H&R, BC Racing, ECS"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
